// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CarpoolParticipant) predicate.CarpoolParticipant {
	return predicate.CarpoolParticipant(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CarpoolParticipant) predicate.CarpoolParticipant {
	return predicate.CarpoolParticipant(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CarpoolParticipant) predicate.CarpoolParticipant {
	return predicate.CarpoolParticipant(sql.NotPredicates(p))
}
